// NOLINTEND(cppcoreguidelines-avoid-magic-numbers,readability-magic-numbers)

std::vector<evgetwindows::HidContact> test::ActiveContacts(const evgetwindows::HidReport& report) {
    auto active = report.contacts | std::views::filter([](const evgetwindows::HidContact& contact) {
                      return contact.tip_down && contact.confident;
                  });
    return {active.begin(), active.end()};
}

std::optional<evgetwindows::HidContact>
test::ContactById(const evgetwindows::HidReport& report, std::uint32_t contact_id) {
    const auto found = std::ranges::find(report.contacts, contact_id, &evgetwindows::HidContact::contact_id);
    if (found == report.contacts.end()) {
        return std::nullopt;
    }
    return *found;
}

bool test::ContactIdsUnique(const evgetwindows::HidReport& report) {
    std::vector<std::uint32_t> ids;
    ids.reserve(report.contacts.size());
    for (const auto& contact : report.contacts) {
        ids.push_back(contact.contact_id);
    }

    std::ranges::sort(ids);
    return std::ranges::adjacent_find(ids) == ids.end();
}

bool test::WithinAxis(const evgetwindows::HidContact& contact, const evgetwindows::HidAxisRange& axis) {
    if (!contact.position_x.has_value() || !contact.position_y.has_value()) {
        return false;
    }

    const auto position_x = contact.position_x.value();
    const auto position_y = contact.position_y.value();
    return position_x >= axis.min_x && position_x <= axis.max_x && position_y >= axis.min_y && position_y <= axis.max_y;
}

void test::ExpectContact(
    const evgetwindows::HidContact& contact,
    const HidContactExpectation& expected,
    const evgetwindows::HidAxisRange& axis
) {
    EXPECT_EQ(contact.contact_id, expected.contact_id);
    EXPECT_EQ(contact.tip_down, expected.tip_down);
    EXPECT_EQ(contact.position_x, std::optional{expected.position_x});
    EXPECT_EQ(contact.position_y, std::optional{expected.position_y});
    EXPECT_TRUE(WithinAxis(contact, axis));
}
